function pivotInteger(n) {
  const total = (n * (n + 1)) / 2;
  const root = Math.sqrt(total);
  const x = Math.round(root);
  if (x * x === total) {
    return x;
  }
  return -1;
}

brute:
function pivotInteger(n) {
  for (let x = 1; x <= n; x++) {
    let low = 0, high = 0;
    for (let k = 1; k <= x; k++) low += k;
    for (let k = x; k <= n; k++) high += k;
    if (low === high) return x;
  }
  return -1;
}

