function generate(rand, size) {
  const pivots = [1, 8, 49, 288];
  if (rand() < 0.3) return [pivots[Math.floor(rand() * pivots.length)]];
  if (size === 'small') return [1 + Math.floor(rand() * 60)];
  return [1 + Math.floor(rand() * 1000)];
}
